def norm(shape):
  minr=min(r for r,c in shape); minc=min(c for r,c in shape)
  return tuple(sorted((r-minr,c-minc) for r,c in shape))
def transforms(shape):
  out=[]
  for refl in [False,True]:
    s=[(r, -c if refl else c) for r,c in shape]
    for k in range(4):
      out.append(norm(s))
      s=[(c,-r) for r,c in s]
  return set(out)
